/**
 * Returns the daily verse for the given calendar date (1..366 day-of-year index).
 */
export function getDailyVerseForDate(date: Date = new Date()): DailyVerseEntry {
  const start = new Date(date.getFullYear(), 0, 0)
  const diff = date.getTime() - start.getTime()
  const dayOfYear = Math.max(1, Math.floor(diff / 86400000))
  return YEARLY_DAILY_VERSES[(dayOfYear - 1) % YEARLY_DAILY_VERSES.length]
}
